import 'package:flutter/material.dart';import 'package:flutter_inappwebview/flutter_inappwebview.dart';import 'paypal_service.dart';class PaypalSubscriptionView extends StatefulWidget {  final Function onSuccess, onCancel, onError;  final String clientId, secretKey;  final String returnUrl, cancelUrl;  final bool sandboxMode;  final String planId;  const PaypalSubscriptionView({    super.key,    required this.onSuccess,    required this.onCancel,    required this.onError,    required this.clientId,    required this.secretKey,    required this.returnUrl,    required this.cancelUrl,    required this.planId,    this.sandboxMode = false,  });  @override  State<PaypalSubscriptionView> createState() => _PaypalSubscriptionViewState();}class _PaypalSubscriptionViewState extends State<PaypalSubscriptionView> {  late PaypalServices services;  String? checkoutUrl;  String accessToken = '';  String subscriptionId = '';  bool _handled = false;  @override  void initState() {    super.initState();    services = PaypalServices(      clientId: widget.clientId,      secretKey: widget.secretKey,      sandboxMode: widget.sandboxMode,    );    _startFlow();  }  Future<void> _startFlow() async {    final tokenRes = await services.getAccessToken();    if (tokenRes['error']) {      widget.onError(tokenRes);      return;    }    accessToken = tokenRes['token'];    final subRes = await services.createSubscription(      planId: widget.planId,      accessToken: accessToken,      returnUrl: widget.returnUrl,      cancelUrl: widget.cancelUrl,    );    setState(() {      checkoutUrl = subRes?['approveUrl'];      subscriptionId = subRes?['id'];    });  }  @override  Widget build(BuildContext context) {    if (checkoutUrl == null) {      return const Scaffold(        body: Center(child: CircularProgressIndicator()),      );    }    return Scaffold(      appBar: AppBar(title: const Text("Subscribe")),      body: InAppWebView(        initialUrlRequest: URLRequest(url: WebUri(checkoutUrl!)),        shouldOverrideUrlLoading: (controller, action) async {          final url = action.request.url;          if (url == null) return NavigationActionPolicy.ALLOW;          if (url.host == Uri.parse(widget.returnUrl).host) {            if (_handled) return NavigationActionPolicy.CANCEL;            _handled = true;            final subId = url.queryParameters['subscription_id'] ?? subscriptionId;            final details = await services.getSubscriptionDetails(subId, accessToken);            if (details?['status'] == 'ACTIVE') {              widget.onSuccess(details);            } else {              widget.onError(details);            }            Navigator.pop(context);            return NavigationActionPolicy.CANCEL;          }          if (url.host == Uri.parse(widget.cancelUrl).host) {            widget.onCancel();            Navigator.pop(context);            return NavigationActionPolicy.CANCEL;          }          return NavigationActionPolicy.ALLOW;        },      ),    );  }}